# ---- Admin (before /{vendor_id}) ----

@router.get("/admin/all", response_model=list[VendorOut])
def admin_list_vendors(
    status_filter: VendorStatus | None = None,
    q: str | None = None,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_admin),
):
    query = db.query(Vendor)
    if status_filter:
        query = query.filter(Vendor.status == status_filter)
    if q:
        like = f"%{q.lower()}%"
        from sqlalchemy import func
        query = query.filter(func.lower(Vendor.name).like(like))
    return [_to_out(v) for v in query.order_by(Vendor.created_at.desc()).limit(500).all()]

@router.put("/admin/{vendor_id}", response_model=VendorOut)
def admin_update_vendor(
    vendor_id: int,
    payload: VendorAdminUpdateIn,
    request: Request,
    db: Session = Depends(get_db),
    current_user: User = Depends(require_admin),
):
    vendor = db.get(Vendor, vendor_id)
    if not vendor:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Vendor not found")
    old_status = vendor.status
    if payload.status is not None:
        vendor.status = payload.status
    if payload.verification_notes is not None:
        vendor.verification_notes = sanitize_plain(payload.verification_notes, max_len=5000)
    audit.record(
        db,
        actor=current_user,
        action="vendor.admin_update",
        target_type="vendor",
        target_id=vendor.id,
        details={"old_status": old_status.value, "new_status": vendor.status.value},
        ip_address=client_ip(request),
    )
    db.commit()
    db.refresh(vendor)
    return _to_out(vendor)

